#!/usr/bin/env node
// The shop's own SOP sheets (docs/sop/) and the owner's guide parts, carried into the code as the built-in help library
// (M25-FR-04 "SOP content"; OB-320, owner, 23 Oct 2026: "the role curriculum is built from the existing SOP sheets and the
// owner guide, one list per role").
//
//   node scripts/sync-sop-library.mjs          — regenerate packages/workforce/src/sop-library.generated.ts
//   node scripts/sync-sop-library.mjs --check  — exit 1 when the generated file is behind the sheets (CI / guardrail)
//
// Each sheet is its English and Tamil file; its version goes up by one whenever either file's text changes (so an
// acknowledgement of the old text is never read as an acknowledgement of the new). Which roles a sheet is for is the
// sheet's own "For:" line, read into role ids by the table below — a PROPOSAL the person publishing it sees and may change
// on screen, and the owner approves the curriculum built from it before it counts.

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';

const SOP_DIR = 'docs/sop';
const GUIDE = 'docs/runbooks/store-computer-owner-guide-windows.md';
const OUT = 'packages/workforce/src/sop-library.generated.ts';

/** Each sheet's "For:" line, read into the roles it names. Change it here when a sheet's audience changes. */
const ROLES_FROM_FOR_LINE = {
  'SOP-01': ['cashier', 'store_manager'], // "everyone at the pilot counter"
  'SOP-02': ['cashier', 'store_manager'], // "the trained person at the pilot counter, named by the owner"
  'SOP-03': ['owner'], // "the owner, every evening after closing"
  'SOP-04': ['cashier', 'owner'], // "the cashier (steps 1–3) and the owner (steps 4–7)"
};
/** The owner guide's parts that are the owner's own set-up and routine (docs/sop/README.md: "Parts 12–30"), and after. */
const OWNER_GUIDE_FROM_PART = 12;

const sha = (s) => createHash('sha256').update(s).digest('hex').slice(0, 16);
const previous = (() => {
  if (!existsSync(OUT)) return new Map();
  const m = new Map();
  for (const x of readFileSync(OUT, 'utf8').matchAll(/"sopId": "(SOP-\d+)",\s*"version": (\d+),\s*"contentHash": "([0-9a-f]+)"/g)) m.set(x[1], { version: Number(x[2]), hash: x[3] });
  return m;
})();

const sheets = [];
for (const en of readdirSync(SOP_DIR).filter((f) => /^sop-\d+-.+\.en\.md$/.test(f)).sort()) {
  const ta = en.replace(/\.en\.md$/, '.ta.md');
  const bodyEn = readFileSync(join(SOP_DIR, en), 'utf8');
  const bodyTa = existsSync(join(SOP_DIR, ta)) ? readFileSync(join(SOP_DIR, ta), 'utf8') : '';
  const sopId = /\*\*Sheet id:\*\*\s*(SOP-\d+)/.exec(bodyEn)?.[1];
  if (sopId === undefined) throw new Error(`${en} has no "Sheet id" line`);
  const title = /^# (.+)$/m.exec(bodyEn)?.[1].replace(/^Sheet \d+ — /, '') ?? sopId;
  const titleTa = /^# (.+)$/m.exec(bodyTa)?.[1].replace(/^தாள் \d+ — /, '') ?? title;
  const forLine = /^\*\*For:\*\*\s*(.+)$/m.exec(bodyEn)?.[1].trim() ?? '';
  const forRoles = ROLES_FROM_FOR_LINE[sopId];
  if (forRoles === undefined) throw new Error(`${sopId} has no role reading in ROLES_FROM_FOR_LINE — add one from its "For:" line ("${forLine}")`);
  const contentHash = sha(`${bodyEn}\u0000${bodyTa}`);
  const prior = previous.get(sopId);
  const version = prior === undefined ? 1 : prior.hash === contentHash ? prior.version : prior.version + 1;
  sheets.push({ sopId, version, contentHash, title, titleTa, forLine, forRoles, category: 'procedure', sourceFiles: [join(SOP_DIR, en), join(SOP_DIR, ta)], bodyEn, bodyTa });
}

const guide = readFileSync(GUIDE, 'utf8');
const parts = [...guide.matchAll(/^## Part (\d+) — (.+)$/gm)].map((m) => ({ part: Number(m[1]), title: m[2].trim() })).filter((p) => p.part >= OWNER_GUIDE_FROM_PART);

const text = `// GENERATED by scripts/sync-sop-library.mjs from docs/sop/*.md and ${GUIDE} — do not edit by hand.
// Run \`node scripts/sync-sop-library.mjs\` after changing a sheet; tests/guardrails/the-help-library-is-the-sheets.test.ts fails
// when this file is behind them.

export interface BuiltInSop {
  readonly sopId: string;
  readonly version: number;
  readonly contentHash: string;
  readonly title: string;
  readonly titleTa: string;
  /** The sheet's own "For:" line, word for word. */
  readonly forLine: string;
  /** The roles that line names (a proposal; whoever publishes it may change it on screen). */
  readonly forRoles: readonly string[];
  readonly category: 'procedure' | 'emergency';
  readonly sourceFiles: readonly string[];
  readonly bodyEn: string;
  readonly bodyTa: string;
}

export interface OwnerGuidePart { readonly part: number; readonly title: string }

export const BUILT_IN_SOPS: readonly BuiltInSop[] = ${JSON.stringify(sheets, null, 2)};

export const OWNER_GUIDE_PARTS: readonly OwnerGuidePart[] = ${JSON.stringify(parts, null, 2)};
`;

if (process.argv.includes('--check')) {
  const now = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  if (now !== text) { console.error(`${OUT} is behind docs/sop — run node scripts/sync-sop-library.mjs`); process.exit(1); }
  console.log(`${OUT} matches the sheets (${sheets.length} sheets, ${parts.length} owner guide parts).`);
} else {
  writeFileSync(OUT, text);
  console.log(`wrote ${OUT}: ${sheets.length} sheets, ${parts.length} owner guide parts.`);
}
